PREFIX ex: <https://spinach.local/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?person ?personLabel ?colleague ?colleagueLabel ?country ?countryLabel ?project ?projectLabel ?paper ?paperLabel WHERE {
  ?person ex:collaboratesWith ?colleague .
  ?person ex:worksAt ?lab1 . ?lab1 ex:locatedIn ?city1 . ?city1 ex:country ?country .
  ?colleague ex:worksAt ?lab2 . ?lab2 ex:locatedIn ?city2 . ?city2 ex:country ?country2 .
  FILTER(?country != ?country2)
  ?person ex:participatesIn ?project . ?colleague ex:participatesIn ?project .
  ?person ex:authored ?paper . ?colleague ex:authored ?paper .
  ?paper ex:status ex:published .
  OPTIONAL { ?person rdfs:label ?personLabel }
  OPTIONAL { ?colleague rdfs:label ?colleagueLabel }
  OPTIONAL { ?country rdfs:label ?countryLabel }
  OPTIONAL { ?project rdfs:label ?projectLabel }
  OPTIONAL { ?paper rdfs:label ?paperLabel }
}

SELECT DISTINCT ?researcher ?name WHERE {
  ?researcher <https://spinach.local/leads> ?project ; <https://spinach.local/worksAt> ?institution .
  ?researcher <https://spinach.local/name> ?name .
  ?institution <https://spinach.local/locatedIn> ?city .
  ?city <https://spinach.local/country> <https://spinach.local/country1> .
  ?project <https://spinach.local/topic> ?topic .
  FILTER(?topic = <https://spinach.local/topic3>)
  FILTER NOT EXISTS {
    ?researcher <https://spinach.local/authored> ?paper .
    ?paper <https://spinach.local/status> <https://spinach.local/retracted> .
  }
}

SELECT DISTINCT ?researcher WHERE {
  ?researcher <https://spinach.local/leads> ?project ; <https://spinach.local/worksAt> ?institution .
  ?institution <https://spinach.local/locatedIn> ?city .
  ?city <https://spinach.local/country> <https://spinach.local/country1> .
  ?project <https://spinach.local/topic> <https://spinach.local/topic3> .
  FILTER NOT EXISTS {
    ?researcher <https://spinach.local/authored> ?paper .
    ?paper <https://spinach.local/status> <https://spinach.local/retracted> .
  }
}

SELECT DISTINCT ?researcher ?project WHERE {
  ?researcher <https://spinach.local/worksAt> ?institution .
  ?institution <https://spinach.local/locatedIn> ?city .
  ?city <https://spinach.local/country> <https://spinach.local/country1> .
  ?researcher <https://spinach.local/leads> ?project .
  ?project <https://spinach.local/topic> <https://spinach.local/topic3> .
  FILTER NOT EXISTS {
    ?paper <https://spinach.local/authored> ?researcher .
    ?paper <https://spinach.local/status> <https://spinach.local/retracted> .
  }
} ORDER BY ?researcher ?project

PREFIX ex: <https://spinach.local/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?project ?projectLabel (SUM(?paperCitations) AS ?totalCitations) WHERE {
  {
    SELECT DISTINCT ?project ?paper ?paperCitations WHERE {
      ?paper ex:status ex:published ;
             ex:citations ?paperCitations ;
             ex:aboutProject ?project .
      ?author ex:authored ?paper ;
              ex:worksAt ?institution .
      ?institution ex:locatedIn ?city .
      ?city ex:country <https://spinach.local/country0> .
    }
  }
  OPTIONAL { ?project rdfs:label ?projectLabel }
}
GROUP BY ?project ?projectLabel
ORDER BY DESC(?totalCitations)

PREFIX ex: <https://spinach.local/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?project ?projectLabel (SUM(?paperCitations) AS ?totalCitations) WHERE {
  {
    SELECT DISTINCT ?paper ?project ?paperCitations WHERE {
      ?author ex:authored ?paper ; ex:worksAt ?institution .
      ?institution ex:locatedIn ?city .
      ?city ex:country ex:country0 .
      ?paper ex:status ex:published ; ex:citations ?paperCitations ; ex:aboutProject ?project .
    }
  }
  ?project rdfs:label ?projectLabel .
}
GROUP BY ?project ?projectLabel
ORDER BY DESC(?totalCitations)

PREFIX ex: <https://spinach.local/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?project ?projectLabel ?researcher ?researcherLabel WHERE {
  ?project ex:topic ex:topic0 ;
           ex:fundedBy ex:funder0 .
  ?researcher ex:participatesIn ?project ;
              ex:worksAt ?institution .
  ?institution ex:locatedIn ?city .
  ?city ex:country ex:country0 .
  OPTIONAL { ?project rdfs:label ?projectLabel }
  OPTIONAL { ?researcher rdfs:label ?researcherLabel }
} ORDER BY ?projectLabel ?researcherLabel

SELECT DISTINCT ?institution ?label WHERE {
  ?institution <https://spinach.local/partnersWith>+ <https://spinach.local/lab7> .
  ?person <https://spinach.local/worksAt> ?institution ;
          <https://spinach.local/leads> ?project .
  ?project <https://spinach.local/topic> <https://spinach.local/topic0> .
  OPTIONAL { ?institution <http://www.w3.org/2000/01/rdf-schema#label> ?label }
} ORDER BY ?institution

PREFIX ex: <https://spinach.local/>
SELECT DISTINCT ?institution ?label WHERE {
  ?institution ex:partnersWith+ ex:lab7 ;
               ?leadPredicate ?leader .
  ?leader ex:leads ?project .
  ?project ex:topic ex:topic0 .
  FILTER(?leadPredicate = ex:employs || ?leadPredicate = ex:worksAt)
  ?institution <http://www.w3.org/2000/01/rdf-schema#label> ?label .
}

PREFIX ex: <https://spinach.local/>
SELECT DISTINCT ?institution ?label WHERE {
  ?institution ex:partnersWith+ ex:lab7 .
  ?leader ex:worksAt ?institution ;
          ex:leads ?project .
  ?project ex:topic ex:topic0 .
  ?institution <http://www.w3.org/2000/01/rdf-schema#label> ?label .
}
